import type { RealtimeChannel } from "@supabase/supabase-js";
import { getSupabase } from "./supabase";

// ──────────────────────────────────────────────────────────────
// Types
// ──────────────────────────────────────────────────────────────

/** Events broadcast on the signaling channel. */
export type SignalEvent =
  | "webrtc-offer"
  | "webrtc-answer"
  | "webrtc-ice"
  | "payment-confirmed"
  | "order-status"
  | "request-token"
  | "assign-token";

export interface SignalPayload {
  /** Unique session identifier (UUID generated by the customer). */
  sessionId: string;
  /** SDP, ICE candidate JSON, or custom payload. */
  data?: RTCSessionDescriptionInit | RTCIceCandidateInit | Record<string, unknown>;
  tokenCode?: string;
  queuePosition?: number;
  printerNumber?: number;
  paymentStatus?: string;
  status?: string;
  errorDetail?: string;
  confirmedAt?: string;
  hasColor?: boolean;
  totalAmount?: number;
  fileCount?: number;
}

// ──────────────────────────────────────────────────────────────
// Channel helpers
// ──────────────────────────────────────────────────────────────

/**
 * Returns the canonical Supabase Realtime Broadcast channel name
 * for a given shop.
 */
export function channelName(shopId: string): string {
  return `signaling:${shopId}`;
}

/**
 * Joins the signaling channel for `shopId` and returns the
 * RealtimeChannel handle so the caller can attach event listeners
 * and broadcast messages.
 *
 * Usage (customer — Next.js):
 * ```ts
 * const ch = joinSignalingChannel("shop-uuid");
 * ch.on("broadcast", { event: "webrtc-answer" }, ({ payload }) => { ... });
 * broadcast(ch, "webrtc-offer", { sessionId, data: offer });
 * ```
 *
 * Usage (shop — Electron):
 * ```ts
 * const ch = joinSignalingChannel("shop-uuid");
 * ch.on("broadcast", { event: "webrtc-offer" }, ({ payload }) => { ... });
 * broadcast(ch, "webrtc-answer", { sessionId, data: answer });
 * ```
 */
const activeChannels = new Map<string, RealtimeChannel>();

/**
 * Joins or retrieves the cached signaling channel for `shopId`.
 * Handles externally-removed channels (e.g. by React cleanup) by
 * detecting unhealthy state and creating a fresh subscription.
 */
export function joinSignalingChannel(shopId: string): RealtimeChannel {
  const existing = activeChannels.get(shopId);
  if (existing) {
    // Supabase channel states: "joined" | "joining" | "leaving" | "closed" | "errored"
    const state = existing.state;
    if (state === "joined" || state === "joining") {
      return existing;
    }
    // Channel was removed or errored — evict from cache
    activeChannels.delete(shopId);
  }

  const supabase = getSupabase();
  const channel = supabase.channel(channelName(shopId), {
    config: { broadcast: { self: false } },
  });

  channel.subscribe((status) => {
    console.log(`[signaling:${shopId}] channel status → ${status}`);
    if (status === "CHANNEL_ERROR" || status === "TIMED_OUT") {
      activeChannels.delete(shopId);
    }
  });

  activeChannels.set(shopId, channel);
  return channel;
}

/**
 * Await channel readiness (state === "joined" / SUBSCRIBED).
 * Resolves `true` when joined, `false` if timeout or channel is dead.
 */
export async function waitForChannelReady(
  channel: RealtimeChannel,
  timeoutMs: number = 3000
): Promise<boolean> {
  if (channel.state === "joined") {
    return true;
  }

  // Dead channel — no point waiting
  if (channel.state === "closed" || channel.state === "errored") {
    return false;
  }

  return new Promise((resolve) => {
    let resolved = false;

    const done = (result: boolean) => {
      if (resolved) return;
      resolved = true;
      clearTimeout(timer);
      clearInterval(checkInterval);
      resolve(result);
    };

    const timer = setTimeout(() => {
      done(channel.state === "joined");
    }, timeoutMs);

    const checkInterval = setInterval(() => {
      if (channel.state === "joined") {
        done(true);
      } else if (channel.state === "closed" || channel.state === "errored") {
        done(false);
      }
    }, 40);
  });
}

/**
 * Convenience wrapper around `channel.send()` for broadcast events.
 */
export async function broadcast(
  channel: RealtimeChannel,
  event: SignalEvent,
  payload: SignalPayload
): Promise<boolean> {
  try {
    const res = await channel.send({
      type: "broadcast",
      event,
      payload,
    });
    if (res !== "ok") {
      console.warn(`[signaling] broadcast ${event} returned status:`, res);
      return false;
    }
    return true;
  } catch (err) {
    console.warn(`[signaling] broadcast ${event} exception:`, err);
    return false;
  }
}

/**
 * Highly resilient, zero-cost public STUN servers for WebRTC NAT traversal.
 * Combines Google, Cloudflare, and Twilio worldwide STUN infrastructures.
 */
export const DEFAULT_ICE_SERVERS: RTCIceServer[] = [
  { urls: "stun:stun.l.google.com:19302" },
  { urls: "stun:stun1.l.google.com:19302" },
  { urls: "stun:stun2.l.google.com:19302" },
  { urls: "stun:stun3.l.google.com:19302" },
  { urls: "stun:stun4.l.google.com:19302" },
  { urls: "stun:stun.cloudflare.com:3478" },
  { urls: "stun:global.stun.twilio.com:3478" },
];

/**
 * Awaits RTCPeerConnection ICE candidate gathering completion or times out after
 * maxWaitMs. This ensures initial host (LAN) and STUN reflexive (public NAT)
 * candidates are directly embedded within the local SDP description,
 * preventing connection failure when trickle ICE broadcast packets are delayed.
 */
export async function waitForIceGathering(
  pc: RTCPeerConnection,
  maxWaitMs: number = 800
): Promise<void> {
  if (pc.iceGatheringState === "complete") {
    return;
  }

  await new Promise<void>((resolve) => {
    let timer: any = null;

    const check = () => {
      if (pc.iceGatheringState === "complete") {
        cleanup();
        resolve();
      }
    };

    const cleanup = () => {
      if (timer) clearTimeout(timer);
      pc.removeEventListener("icegatheringstatechange", check);
    };

    timer = setTimeout(() => {
      cleanup();
      resolve();
    }, maxWaitMs);

    pc.addEventListener("icegatheringstatechange", check);
  });
}

